    let _program = args.next();

    match args.next() {
        Some(value) => parse_c_atoi_i32(&value),
        None => 1,
    }
}

fn parse_c_atoi_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let limit = if negative {
        (i64::MAX as i128) + 1
    } else {
        i64::MAX as i128
    };

    let mut saw_digit = false;
    let mut value = 0i128;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        saw_digit = true;
        value = value
            .saturating_mul(10)
            .saturating_add((bytes[index] - b'0') as i128);
        if value > limit {
            value = limit;
        }
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = if negative { -value } else { value };
    let clamped = signed.clamp(i64::MIN as i128, i64::MAX as i128) as i64;
    clamped as i32
}

