pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_regular_polygon(n: i32) -> Polygon {
    let vertex_count = n.wrapping_mul(3);
    let mut polygon = Vec::with_capacity(1);
    let mut ring = Vec::new();

    if vertex_count > 0 {
        let total = vertex_count as f64;
        for index in 0..vertex_count {
            let angle = 2.0 * std::f64::consts::PI * (index as f64) / total;
            ring.push([angle.cos(), angle.sin()]);
        }
    }

    polygon.push(ring);
    polygon
}

