const EPSILON: f64 = 1e-12;

pub fn earcut(polygon: &[Ring]) -> Vec<u32> {
    let Some(ring) = polygon.first() else {
        return Vec::new();
    };

    if ring.len() < 3 {
        return Vec::new();
    }

    let orientation = signed_area(ring);
    if orientation.abs() <= EPSILON {
        return Vec::new();
    }

    let ccw = orientation > 0.0;
    let mut vertices: Vec<usize> = (0..ring.len()).collect();
    let mut indices = Vec::with_capacity((ring.len() - 2) * 3);
    let mut ear_pos = vertices.len() - 1;
    let mut stalled = 0usize;

    while vertices.len() > 2 {
        let len = vertices.len();
        let prev_pos = if ear_pos == 0 { len - 1 } else { ear_pos - 1 };
        let next_pos = if ear_pos + 1 == len { 0 } else { ear_pos + 1 };

        if is_ear(ring, &vertices, prev_pos, ear_pos, next_pos, ccw) {
            indices.extend([
                vertices[prev_pos] as u32,
                vertices[ear_pos] as u32,
                vertices[next_pos] as u32,
            ]);

            vertices.remove(ear_pos);
            stalled = 0;

            if vertices.len() <= 2 {
                break;
            }

            let next_index = if next_pos == 0 { 0 } else { ear_pos };
            ear_pos = (next_index + 1) % vertices.len();
        } else {
            ear_pos = next_pos;
            stalled += 1;

            if stalled > len * len {
                break;
            }
        }
    }

    indices
}

fn is_ear(
    ring: &[Point],
    vertices: &[usize],
    prev_pos: usize,
    ear_pos: usize,
    next_pos: usize,
    ccw: bool,
) -> bool {
    let prev = ring[vertices[prev_pos]];
    let ear = ring[vertices[ear_pos]];
    let next = ring[vertices[next_pos]];

    let triangle_area = cross(prev, ear, next);
    if ccw {
        if triangle_area <= EPSILON {
            return false;
        }
    } else if triangle_area >= -EPSILON {
        return false;
    }

    for (position, &vertex) in vertices.iter().enumerate() {
        if position == prev_pos || position == ear_pos || position == next_pos {
