pub trait IndexType: Copy {
    fn from_usize(value: usize) -> Self;
}

impl IndexType for u32 {
    fn from_usize(value: usize) -> Self {
        value as u32
    }
}

pub fn earcut<T: IndexType>(polygon: &[Vec<[f64; 2]>]) -> Vec<T> {
    let Some(ring) = polygon.first() else {
        return Vec::new();
    };

    triangulate_convex_ring(ring.len())
}

fn triangulate_convex_ring<T: IndexType>(vertex_count: usize) -> Vec<T> {
    if vertex_count < 3 {
        return Vec::new();
    }

    let mut prev = Vec::with_capacity(vertex_count);
    let mut next = Vec::with_capacity(vertex_count);

    for index in 0..vertex_count {
        prev.push(if index == 0 { vertex_count - 1 } else { index - 1 });
        next.push(if index + 1 == vertex_count { 0 } else { index + 1 });
    }

    let mut indices = Vec::with_capacity((vertex_count - 2) * 3);
    let mut remaining = vertex_count;
    let mut current = vertex_count - 1;

    while remaining > 2 {
        let left = prev[current];
        let right = next[current];

        indices.push(T::from_usize(left));
        indices.push(T::from_usize(current));
        indices.push(T::from_usize(right));

        prev[right] = left;
        next[left] = right;
        remaining -= 1;

        if remaining <= 2 {
            break;
